func NewHashedValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (HashedValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing HashedValue Attribute Value",
				"While creating a HashedValue value, a missing attribute value was detected. "+
					"A HashedValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("HashedValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid HashedValue Attribute Type",
				"While creating a HashedValue value, an invalid attribute value was detected. "+
					"A HashedValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("HashedValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("HashedValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra HashedValue Attribute Value",
				"While creating a HashedValue value, an extra attribute value was detected. "+
					"A HashedValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra HashedValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewHashedValueUnknown(), diags
	}

	aggregationAttribute, ok := attributes["aggregation"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`aggregation is missing from object`)

		return NewHashedValueUnknown(), diags
	}

	aggregationVal, ok := aggregationAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`aggregation expected to be basetypes.StringValue, was: %T`, aggregationAttribute))
	}

	aggregationCriteriaAttribute, ok := attributes["aggregation_criteria"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`aggregation_criteria is missing from object`)

		return NewHashedValueUnknown(), diags
	}

	aggregationCriteriaVal, ok := aggregationCriteriaAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`aggregation_criteria expected to be basetypes.StringValue, was: %T`, aggregationCriteriaAttribute))
	}

	isIdentityColAttribute, ok := attributes["is_identity_col"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`is_identity_col is missing from object`)

		return NewHashedValueUnknown(), diags
	}

	isIdentityColVal, ok := isIdentityColAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`is_identity_col expected to be basetypes.BoolValue, was: %T`, isIdentityColAttribute))
	}

	outputColAttribute, ok := attributes["output_col"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`output_col is missing from object`)

		return NewHashedValueUnknown(), diags
	}

	outputColVal, ok := outputColAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`output_col expected to be basetypes.StringValue, was: %T`, outputColAttribute))
	}

	scopeColAttribute, ok := attributes["scope_col"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`scope_col is missing from object`)

		return NewHashedValueUnknown(), diags
	}

	scopeColVal, ok := scopeColAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`scope_col expected to be basetypes.StringValue, was: %T`, scopeColAttribute))
	}

	if diags.HasError() {
		return NewHashedValueUnknown(), diags
	}

	return HashedValue{
		Aggregation:         aggregationVal,
		AggregationCriteria: aggregationCriteriaVal,
		IsIdentityCol:       isIdentityColVal,
		OutputCol:           outputColVal,
		ScopeCol:            scopeColVal,
		state:               attr.ValueStateKnown,
	}, diags
}

func NewHashedValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) HashedValue {
	object, diags := NewHashedValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewHashedValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t HashedType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewHashedValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewHashedValueUnknown(), nil
	}

	if in.IsNull() {
		return NewHashedValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewHashedValueMust(HashedValue{}.AttributeTypes(ctx), attributes), nil
}

