func NewReferencedValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (ReferencedValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing ReferencedValue Attribute Value",
				"While creating a ReferencedValue value, a missing attribute value was detected. "+
					"A ReferencedValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("ReferencedValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid ReferencedValue Attribute Type",
				"While creating a ReferencedValue value, an invalid attribute value was detected. "+
					"A ReferencedValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("ReferencedValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("ReferencedValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra ReferencedValue Attribute Value",
				"While creating a ReferencedValue value, an extra attribute value was detected. "+
					"A ReferencedValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra ReferencedValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewReferencedValueUnknown(), diags
	}

	aggregationAttribute, ok := attributes["aggregation"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`aggregation is missing from object`)

		return NewReferencedValueUnknown(), diags
	}

	aggregationVal, ok := aggregationAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`aggregation expected to be basetypes.StringValue, was: %T`, aggregationAttribute))
	}

	aggregationCriteriaAttribute, ok := attributes["aggregation_criteria"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`aggregation_criteria is missing from object`)

		return NewReferencedValueUnknown(), diags
	}

	aggregationCriteriaVal, ok := aggregationCriteriaAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`aggregation_criteria expected to be basetypes.StringValue, was: %T`, aggregationCriteriaAttribute))
	}

	isIdentityColAttribute, ok := attributes["is_identity_col"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`is_identity_col is missing from object`)

		return NewReferencedValueUnknown(), diags
	}

	isIdentityColVal, ok := isIdentityColAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`is_identity_col expected to be basetypes.BoolValue, was: %T`, isIdentityColAttribute))
	}

	outputColAttribute, ok := attributes["output_col"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`output_col is missing from object`)

		return NewReferencedValueUnknown(), diags
	}

	outputColVal, ok := outputColAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`output_col expected to be basetypes.StringValue, was: %T`, outputColAttribute))
	}

	scopeColAttribute, ok := attributes["scope_col"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`scope_col is missing from object`)

		return NewReferencedValueUnknown(), diags
	}

	scopeColVal, ok := scopeColAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`scope_col expected to be basetypes.StringValue, was: %T`, scopeColAttribute))
	}

	if diags.HasError() {
		return NewReferencedValueUnknown(), diags
	}

	return ReferencedValue{
		Aggregation:         aggregationVal,
		AggregationCriteria: aggregationCriteriaVal,
		IsIdentityCol:       isIdentityColVal,
		OutputCol:           outputColVal,
		ScopeCol:            scopeColVal,
		state:               attr.ValueStateKnown,
	}, diags
}

