func NewPopulationValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (PopulationValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing PopulationValue Attribute Value",
				"While creating a PopulationValue value, a missing attribute value was detected. "+
					"A PopulationValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("PopulationValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid PopulationValue Attribute Type",
				"While creating a PopulationValue value, an invalid attribute value was detected. "+
					"A PopulationValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("PopulationValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("PopulationValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra PopulationValue Attribute Value",
				"While creating a PopulationValue value, an extra attribute value was detected. "+
					"A PopulationValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra PopulationValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewPopulationValueUnknown(), diags
	}

	cohortIdsAttribute, ok := attributes["cohort_ids"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`cohort_ids is missing from object`)

		return NewPopulationValueUnknown(), diags
	}

	cohortIdsVal, ok := cohortIdsAttribute.(basetypes.ListValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`cohort_ids expected to be basetypes.ListValue, was: %T`, cohortIdsAttribute))
	}

	exclusionAddressLevelCohortIdsAttribute, ok := attributes["exclusion_address_level_cohort_ids"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`exclusion_address_level_cohort_ids is missing from object`)

		return NewPopulationValueUnknown(), diags
	}

	exclusionAddressLevelCohortIdsVal, ok := exclusionAddressLevelCohortIdsAttribute.(basetypes.ListValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`exclusion_address_level_cohort_ids expected to be basetypes.ListValue, was: %T`, exclusionAddressLevelCohortIdsAttribute))
	}

	exclusionCohortIdsAttribute, ok := attributes["exclusion_cohort_ids"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`exclusion_cohort_ids is missing from object`)

		return NewPopulationValueUnknown(), diags
	}

	exclusionCohortIdsVal, ok := exclusionCohortIdsAttribute.(basetypes.ListValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`exclusion_cohort_ids expected to be basetypes.ListValue, was: %T`, exclusionCohortIdsAttribute))
	}

	if diags.HasError() {
		return NewPopulationValueUnknown(), diags
	}

	return PopulationValue{
		CohortIds:                      cohortIdsVal,
		ExclusionAddressLevelCohortIds: exclusionAddressLevelCohortIdsVal,
		ExclusionCohortIds:             exclusionCohortIdsVal,
		state:                          attr.ValueStateKnown,
	}, diags
}

func NewPopulationValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) PopulationValue {
	object, diags := NewPopulationValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewPopulationValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t PopulationType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewPopulationValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewPopulationValueUnknown(), nil
	}

	if in.IsNull() {
		return NewPopulationValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewPopulationValueMust(PopulationValue{}.AttributeTypes(ctx), attributes), nil
}

func (t PopulationType) ValueType(ctx context.Context) attr.Value {
	return PopulationValue{}
}

