type PopulationValue struct {
	CohortIds                      basetypes.ListValue `tfsdk:"cohort_ids"`
	ExclusionAddressLevelCohortIds basetypes.ListValue `tfsdk:"exclusion_address_level_cohort_ids"`
	ExclusionCohortIds             basetypes.ListValue `tfsdk:"exclusion_cohort_ids"`
	state                          attr.ValueState
}

func (v PopulationValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 3)

	var val tftypes.Value
	var err error

	attrTypes["cohort_ids"] = basetypes.ListType{
		ElemType: types.StringType,
	}.TerraformType(ctx)
	attrTypes["exclusion_address_level_cohort_ids"] = basetypes.ListType{
		ElemType: types.StringType,
	}.TerraformType(ctx)
	attrTypes["exclusion_cohort_ids"] = basetypes.ListType{
		ElemType: types.StringType,
	}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 3)

		val, err = v.CohortIds.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["cohort_ids"] = val

		val, err = v.ExclusionAddressLevelCohortIds.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["exclusion_address_level_cohort_ids"] = val

		val, err = v.ExclusionCohortIds.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["exclusion_cohort_ids"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v PopulationValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v PopulationValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

